Lemma w4s32_shift_ok : forall tl mtl, 1 <= tl <= 12 -> 1 <= mtl <= 12 ->
  Z.land (Z.land (bv_swrap 32 (0 - (tl + 256 * mtl))) 18446744073709551615) 63 = 64 - tl.
Proof.
