Lemma w4s32_pre : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x16 x17 x18 x19 x20 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 :
          word)
         (P PE PP BITS tl mtl : Z) (w224 : word),
    rw_cells asegs mm (P + 200) [C8 (Z_to_bv 64 PE)] ->
    rw_cells asegs mm (P + 104) [C8 (Z_to_bv 64 (tl + 256 * mtl))] ->
    rw_cells asegs mm (P + 224) [C8 w224] ->
    mem_inv asegs mm ->
    rng RNG P 496 ->
    rng_aimg RNG ->
    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    0 <= PP <= PE ->
    PE < 2^47 ->
    0 <= BITS < 2^64 ->
    1 <= tl <= 12 ->
    1 <= mtl <= 12 ->
    (PE - PP < 4 -> forall (y11 y12 : word),
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 y11 y12 x13 x14 (Z_to_bv 64 PP) x16 x17 x18 x19
           x20 (Z_to_bv 64 BITS) x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x9218c) fc None mm (seg_rom
           asegs))) ->
    (4 <= PE - PP -> 64 < BITS -> forall (y11 y12 y17 : word),
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 y11 y12 x13 x14 (Z_to_bv 64 PP) x16 y17 x18 x19
           x20 (Z_to_bv 64 (tl + 256 * mtl)) x22 x23 x24 x25 x26 x27 (Z_to_bv 64 BITS) (Z_to_bv 64 PE) x30 w224) F
           (Z_to_bv 64 0x9232c) fc None mm (seg_rom asegs))) ->
    (4 <= PE - PP -> BITS <= 64 -> forall (y12 : word),
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) x6 x7 x8 x9 x10 (Z_to_bv 64 PP) y12 x13 x14
           (Z_to_bv 64 PP) x16 (Z_to_bv 64 64) x18 x19 x20 (Z_to_bv 64 BITS) x22 x23 x24 x25 x26 x27 (Z_to_bv 64 (64 -
           tl)) x29 x30 x31) F (Z_to_bv 64 0x91e84) fc None mm (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 (Z_to_bv 64 PP) x16 x17 x18 x19
        x20 (Z_to_bv 64 BITS) x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x91e48) fc None mm (seg_rom
        asegs)).
