(* [comment removed for export] *)
Lemma w4s32_Hc : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x16 x17 x19 x20 x22 x23 x24 x26 x27 x28 x29 x30 x31 : word)
         (P S2 PTR BITS PP : Z),
    rw_cells asegs mm (P + 184) [C8 (Z_to_bv 64 (S2 + 8))] ->
    mem_inv asegs mm ->
    rng RNG P 496 ->
    rng_aimg RNG ->
    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    S2 < PTR < S2 + 8 ->
    8 <= S2 ->
    S2 + 8 < 2^47 ->
    0 <= BITS <= 64 ->
    (S2 <= PTR - BITS / 8 -> evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 x12 (Z_to_bv 64 (BITS / 8)) (Z_to_bv 64 (PTR
           - BITS / 8)) (Z_to_bv 64 PP) x16 x17 (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 BITS) x22 x23 x24 (Z_to_bv 64 PTR)
           x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x91ea0) fc None mm (seg_rom asegs))) ->
    (PTR - BITS / 8 < S2 -> evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 x12 (Z_to_bv 64 (BITS / 8)) (Z_to_bv 64 (PTR
           - BITS / 8)) (Z_to_bv 64 PP) x16 x17 (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 BITS) x22 x23 x24 (Z_to_bv 64 PTR)
           x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x91e9c) fc None mm (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 (Z_to_bv 64 PP) x16 x17 (Z_to_bv
        64 S2) x19 x20 (Z_to_bv 64 BITS) x22 x23 x24 (Z_to_bv 64 PTR) x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x91e84)
