Lemma w4s32_Re : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x16 x17 x19 x20 x22 x23 x24 x26 x27 x28 x29 x30 x31 : word)
         (P S2 PP BITS DESC PE : Z) (w224 : word),
    rw_cells asegs mm (P + 184) [C8 (Z_to_bv 64 (S2 + 8))] ->
    rw_cells asegs mm (P + 104) [C8 (Z_to_bv 64 DESC)] ->
    rw_cells asegs mm (P + 200) [C8 (Z_to_bv 64 PE)] ->
    rw_cells asegs mm (P + 224) [C8 w224] ->
    mem_inv asegs mm ->
