    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    0 <= S2 < 2^47 - 8 ->
    0 <= BITS < 2^64 ->
    (forall (y13 : word),
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 (Z_to_bv 64 S2) y13 x14 (Z_to_bv 64 PP) x16
           x17 (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 DESC) x22 x23 x24 (Z_to_bv 64 S2) x26 x27 (Z_to_bv 64 BITS)
           (Z_to_bv 64 PE) x30 w224) F (Z_to_bv 64 0x9232c) fc None mm (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 (Z_to_bv 64 PP) x16 x17 (Z_to_bv
        64 S2) x19 x20 (Z_to_bv 64 BITS) x22 x23 x24 (Z_to_bv 64 S2) x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x91e84)
