    1 <= tl <= 12 ->
    1 <= mtl <= 12 ->
    (PE <= PP -> evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 (Z_to_bv 64 PP) x16 x17 x18 x19
